import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Product { id: string; name: string; priceMinor: number; }
export interface CreateProduct { name: string; priceMinor: number; }

@Injectable({ providedIn: 'root' })
export class CatalogApi {
  private readonly http = inject(HttpClient);
  private readonly base = '/api/products';

  list(search = ''): Observable<Product[]> {
    const params = new HttpParams().set('search', search);
    return this.http.get<Product[]>(this.base, { params });
  }
  create(dto: CreateProduct): Observable<Product> {
    return this.http.post<Product>(this.base, dto);
  }
  replace(id: string, dto: CreateProduct): Observable<Product> {
    return this.http.put<Product>(`${this.base}/${encodeURIComponent(id)}`, dto);
  }
  updatePrice(id: string, priceMinor: number): Observable<Product> {
    return this.http.patch<Product>(`${this.base}/${encodeURIComponent(id)}`, { priceMinor });
  }
  remove(id: string): Observable<void> {
    return this.http.delete<void>(`${this.base}/${encodeURIComponent(id)}`);
  }
}
