import { HttpInterceptorFn, provideHttpClient, withInterceptors } from '@angular/common/http';
import { ApplicationConfig } from '@angular/core';

let nextRequestNumber = 0;
export const requestIdInterceptor: HttpInterceptorFn = (req, next) => {
  // Demo-only deterministic identifier; use a suitable random/trace ID policy in production.
  if (!req.url.startsWith('/api/')) return next(req);
  const requestId = `demo-request-${++nextRequestNumber}`;
  const updated = req.clone({ setHeaders: { 'X-Request-ID': requestId } });
  return next(updated);
};

export const appConfig: ApplicationConfig = {
  providers: [provideHttpClient(withInterceptors([requestIdInterceptor]))]
};

