import { HttpErrorResponse } from '@angular/common/http';

export type UserFacingError = 'sign-in' | 'forbidden' | 'missing' | 'bad-request' | 'server' | 'network';

export function classifyHttpError(error: HttpErrorResponse): UserFacingError {
  switch (error.status) {
    case 0: return 'network'; // Browser transport failure, CORS, offline or abort scenarios.
    case 400: return 'bad-request';
    case 401: return 'sign-in';
    case 403: return 'forbidden';
    case 404: return 'missing';
    default: return error.status >= 500 ? 'server' : 'bad-request';
  }
}

export function userMessage(kind: UserFacingError): string {
  const messages: Record<UserFacingError, string> = {
    'sign-in': 'Please sign in again.',
    forbidden: 'You do not have access to this resource.',
    missing: 'The requested resource is not available.',
    'bad-request': 'Please review the submitted information.',
    server: 'Service is temporarily unavailable. Try again later.',
    network: 'Cannot reach the service. Check your connection.'
  };
  return messages[kind];
}

import { Component, Injectable, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { take } from 'rxjs';

interface Appointment { id: string; startAt: string; }
type LoadState =
  | { kind: 'idle' }
  | { kind: 'loading' }
  | { kind: 'success'; items: Appointment[] }
  | { kind: 'empty' }
  | { kind: 'error'; message: string };

@Injectable({ providedIn: 'root' })
export class AppointmentApi {
  private readonly http = inject(HttpClient);
  list() { return this.http.get<Appointment[]>('/api/appointments').pipe(take(1)); }
}

@Component({
  standalone: true,
  selector: 'app-appointments',
  template: `
    <button type="button" (click)="load()">Refresh appointments</button>
    @switch (state().kind) {
      @case ('idle') { <p>Choose Refresh to load appointments.</p> }
      @case ('loading') { <p role="status">Loading appointments…</p> }
      @case ('empty') { <p>No appointments were found.</p> }
      @case ('error') {
        <p role="alert">Unable to load appointments.</p>
        <button type="button" (click)="load()">Try again</button>
      }
      @case ('success') {
        @if (items().length > 0) {
          <ul>@for (item of items(); track item.id) {
            <li>Appointment {{ item.id }}: {{ item.startAt }}</li>
          }</ul>
        }
      }
    }
  `
})
export class AppointmentsComponent {
  private readonly api = inject(AppointmentApi);
  readonly state = signal<LoadState>({ kind: 'idle' });
  readonly items = () => {
    const value = this.state();
    return value.kind === 'success' ? value.items : [];
  };
  load(): void {
    this.state.set({ kind: 'loading' });
    this.api.list().subscribe({
      next: items => this.state.set(items.length ? { kind: 'success', items } : { kind: 'empty' }),
      error: () => this.state.set({ kind: 'error', message: 'Request failed' })
    });
  }
}

import { Component, Injectable, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';

interface Transaction {
  id: string;
  type: 'credit' | 'debit';
  currency: string;
  amountMinor: number;
}
type TransactionState =
  | { kind: 'idle' }
  | { kind: 'loading' }
  | { kind: 'empty' }
  | { kind: 'success'; rows: Transaction[] }
  | { kind: 'error' };

@Injectable({ providedIn: 'root' })
export class TransactionApi {
  private readonly http = inject(HttpClient);
  list() { return this.http.get<Transaction[]>('/api/transactions'); }
}

@Component({
  standalone: true,
  selector: 'app-transaction-list',
  template: `
    <h2>Fictional transactions</h2>
    <button type="button" [disabled]="state().kind === 'loading'" (click)="load()">Load</button>
    @switch (state().kind) {
      @case ('idle') { <p>Load to see your history.</p> }
      @case ('loading') { <p role="status">Loading transaction history…</p> }
      @case ('empty') { <p>No transactions found.</p> }
      @case ('error') {
        <p role="alert">Could not load transactions. Please try again.</p>
        <button type="button" (click)="load()">Retry</button>
      }
      @case ('success') {
        <ul>
          @for (row of rows(); track row.id) {
            <li>{{ row.type }}: {{ formatAmount(row) }}</li>
          }
        </ul>
      }
    }
  `
})
export class TransactionListComponent {
  private readonly api = inject(TransactionApi);
  readonly state = signal<TransactionState>({ kind: 'idle' });
  readonly rows = () => {
    const s = this.state();
    return s.kind === 'success' ? s.rows : [];
  };

  load(): void {
    this.state.set({ kind: 'loading' });
    this.api.list().subscribe({
      next: rows => this.state.set(rows.length ? { kind: 'success', rows } : { kind: 'empty' }),
      error: () => this.state.set({ kind: 'error' })
    });
  }

  formatAmount(row: Transaction): string {
    return new Intl.NumberFormat('en-US', {
      style: 'currency', currency: row.currency
    }).format(row.amountMinor / 100);
  }
}
